// src/js/animations/volleyball.js
// 使用本機 ESM GSAP（核心 + CSSPlugin）。不需要 MotionPath。
import { gsap } from '../../library/gsap/gsap-core.js';
import { CSSPlugin } from '../../library/gsap/CSSPlugin.js';
gsap.registerPlugin(CSSPlugin);

/* ------------------------------------
1) 物理模擬：回傳 samples = [{x,y,dt,rot,phase}]
------------------------------------ */
function simulateTrajectory(opt) {
	const {
		g, rho, Cd, r, m,
		netX, wallX,
		x0, y0, speed, angleDeg,
		e, muK, muR, rollYThreshold, eWall,
		muRReturnMultiplier,
		simDT, tmax,

		// 旋轉
		spinRPS, spinDir, spinAirDamping, groundSpinBlend, wallSpinLoss, spinVisualMultiplier
	} = opt;

	const A = Math.PI * r * r;
	const theta = (180 - angleDeg) * Math.PI / 180; // 右→左
	let x = x0, y = y0;
	let vx = speed * Math.cos(theta);
	let vy = speed * Math.sin(theta);
	let phase = 'flight';
	let hitWall = false;

	// 自旋
	let omega = 2 * Math.PI * (spinRPS || 0) * (spinDir || 1); // rad/s
	let thetaAcc = 0; // 累積角度（rad）

	const samples = []; // {x, y, dt, rot, phase}
	let t = 0, steps = 0;

	const accel = (vx, vy) => {
		const v = Math.hypot(vx, vy);
		let ax = 0, ay = -g;
		if (v > 0) {
			const Fd = 0.5 * rho * Cd * A * v * v;
			ax += -(Fd / m) * (vx / v);
			ay += -(Fd / m) * (vy / v);
		}
		return { ax, ay };
	};

	const rk4 = (x, y, vx, vy, dt) => {
		const f = (x, y, vx, vy) => { const a = accel(vx, vy); return [vx, vy, a.ax, a.ay]; };
		const k1 = f(x, y, vx, vy);
		const k2 = f(x + 0.5 * dt * k1[0], y + 0.5 * dt * k1[1], vx + 0.5 * dt * k1[2], vy + 0.5 * dt * k1[3]);
		const k3 = f(x + 0.5 * dt * k2[0], y + 0.5 * dt * k2[1], vx + 0.5 * dt * k2[2], vy + 0.5 * dt * k2[3]);
		const k4 = f(x + dt * k3[0], y + dt * k3[1], vx + dt * k3[2], vy + dt * k3[3]);
		return [
			x  + dt * (k1[0] + 2*k2[0] + 2*k3[0] + k4[0]) / 6,
			y  + dt * (k1[1] + 2*k2[1] + 2*k3[1] + k4[1]) / 6,
			vx + dt * (k1[2] + 2*k2[2] + 2*k3[2] + k4[2]) / 6,
			vy + dt * (k1[3] + 2*k2[3] + 2*k3[3] + k4[3]) / 6,
		];
	};

	const EPS = 1e-3;
	const VX_MIN_AFTER_WALL = 0.15;
	const NEAR_GROUND_Y     = r + 0.03;
	const SMALL_VY_FOR_ROLL = 1.0;

	const push = (xx, yy, dt, ph) => {
		const dtClamped = Math.max(0, dt || 0);
		// 累積旋轉（帶視覺倍率）
		thetaAcc += (omega * dtClamped) * (spinVisualMultiplier || 1);
		// 空中自旋線性衰減
		omega += -(spinAirDamping || 0) * omega * dtClamped;

		if (xx <= netX + 0.0005) {
			samples.push({ x: xx, y: yy, dt: dtClamped, rot: thetaAcc, phase: ph || phase });
		}
	};

	push(x, y, 0, phase);

	while (t < tmax && steps < 60000) {
		const xPrev = x, yPrev = y, vxPrev = vx, vyPrev = vy;

		if (phase === 'flight') {
			[x, y, vx, vy] = rk4(x, y, vx, vy, simDT);

			// 地面反彈
			if (y <= r && vy < 0) {
				y = r;
				vy = -vy * e;
				vx *= (1 - muK);

				// 自旋向「無滑動」靠攏
				const targetOmega = (vx / r);
				const blend = Math.min(1, Math.max(0, groundSpinBlend));
				omega = (1 - blend) * omega + blend * targetOmega;

				if (hitWall && x - r <= wallX + 0.05) {
					if (Math.abs(vy) < Math.max(rollYThreshold, 0.8)) { vy = 0; phase = 'roll'; }
				} else if (Math.abs(vy) < rollYThreshold) {
					vy = 0; phase = 'roll';
				}
			}

			// 牆：連續碰撞偵測
			const prevPen = (xPrev - r) - wallX;
			const currPen = (x - r)   - wallX;
			if (vxPrev < 0 && prevPen > 0 && currPen <= EPS) {
				const denom = (xPrev - x) || 1e-9;
				const alpha = Math.max(0, Math.min(1, (xPrev - r - wallX) / denom));
				const xi  = xPrev  + alpha * (x  - xPrev);
				const yi  = yPrev  + alpha * (y  - yPrev);
				const vxi = vxPrev + alpha * (vx - vxPrev);
				const vyi = vyPrev + alpha * (vy - vyPrev);

				const dt1 = alpha * simDT;
				if (dt1 > 0) push(xi, yi, dt1, 'flight');

				let vxAfter = Math.max(VX_MIN_AFTER_WALL, -vxi * eWall);
				let vyAfter = vyi;

				// 牆面自旋損失
				omega *= (1 - Math.min(1, Math.max(0, wallSpinLoss)));

				if (yi <= NEAR_GROUND_Y && Math.abs(vyAfter) < SMALL_VY_FOR_ROLL) {
					x = wallX + r + EPS;
					y = r;
					vx = vxAfter;
					vy = 0;
					phase = 'roll';
					hitWall = true;

					const dt2 = (1 - alpha) * simDT;
					if (dt2 > 0) push(x, y, dt2, 'roll');
				} else {
					x = wallX + r + EPS;
					y = yi;
					vx = vxAfter;
					vy = vyAfter;
					hitWall = true;

					let rem = (1 - alpha) * simDT;
					const subN = 3, subDT = rem / subN;
					for (let k = 0; k < subN; k++) {
						[x, y, vx, vy] = rk4(x, y, vx, vy, subDT);
						push(x, y, subDT, 'flight');
					}
				}

				t += simDT;
				steps++;
				continue;
			}

			push(x, y, simDT, 'flight');

		} else {
			// 滾動（無滑動）
			const mu = hitWall ? muR * muRReturnMultiplier : muR;
			const a = -mu * g * Math.sign(vx);
			vx += a * simDT;
			if (Math.sign(vx) !== Math.sign(vx - a * simDT)) vx = 0;
			x += vx * simDT;
			y = r;

			omega = (vx / r);

			if (vx < 0 && x - r <= wallX + EPS) {
				x = wallX + r + EPS;
				vx = Math.max(VX_MIN_AFTER_WALL, -vx * eWall);
				omega *= (1 - Math.min(1, Math.max(0, wallSpinLoss)));
				hitWall = true;
			}

			push(x, y, simDT, 'roll');

			if (Math.abs(vx) < 1e-3 && x > wallX + r + 0.01) break;
		}

		t += simDT;
		steps++;
	}

	if (samples.length < 2) samples.push({ x: x0, y: y0, dt: simDT, rot: thetaAcc, phase });
	return samples;
}

/* ----------------------------------------------------
2) Keyframes 壓縮（考量位移＋旋轉，滾動更嚴格、尾端保護）
---------------------------------------------------- */
function compressKeyframesSmart(kfs, {
	minDt = 1 / 90,
	pxTol = 0.6,
	rotTolDeg = 8,
	minDtRoll = 1 / 240,
	pxTolRoll = 0.25,
	tailProtect = 0.6 // 秒
} = {}) {
	if (!kfs || kfs.length <= 2) return kfs || [];

	const total = kfs.reduce((s, k) => s + (k.duration || 0), 0);
	let accTime = 0;
	const timeFromEnd = kfs.map(k => (accTime += (k.duration || 0), total - accTime));

	const out = [];
	let acc = { ...kfs[0] };

	for (let i = 1; i < kfs.length; i++) {
		const k = kfs[i];
		const phaseChanged = (k.phase !== acc.phase);
		const inTail = (timeFromEnd[i - 1] < tailProtect || timeFromEnd[i] < tailProtect);

		const isRoll = (k.phase === 'roll' || acc.phase === 'roll');
		const dMin = isRoll ? minDtRoll : minDt;
		const pTol = isRoll ? pxTolRoll : pxTol;

		const dist = Math.hypot(k.x - acc.x, k.y - acc.y);
		const drot = Math.abs((k.rotation ?? 0) - (acc.rotation ?? 0));

		const canMerge = !phaseChanged && !inTail && (acc.duration < dMin || dist < pTol) && drot < rotTolDeg;

		if (canMerge) {
			acc.duration += k.duration || 0;
			acc.x = k.x; acc.y = k.y; acc.rotation = k.rotation; acc.phase = k.phase;
		} else {
			out.push(acc);
			acc = { ...k };
		}
	}
	out.push(acc);
	return out;
}

/* -------------------------------------------------
3) 主模組：位移給外層 <g>，旋轉直接套在 <image>
   ＋ 相機裁切/縮放（camera）＋ 螢幕內邊距（screen padding）
------------------------------------------------- */
export function initVolleyball(container, userOptions = {}) {
	if (!container) { console.warn('[volleyball] container not found'); return null; }
	if (container.classList && container.classList.contains('svgContainer')) {
		console.warn('[volleyball] 請把動畫掛在專用容器（如 #vbScene），避免覆蓋其他 SVG');
		return null;
	}

	const defaults = {
		// 物理與場域（世界座標：公尺）
		g: 9.81,						// 重力加速度（m/s²）
		rho: 1.225,						// 空氣密度（kg/m³）
		Cd: 0.47,						// 球體阻力係數
		r: 0.105,						// 球半徑（m）
		m: 0.27,						// 球質量（kg）
		netX: 3.8,						// 右側邊界 = 網子位置（m）
		wallX: -10,						// 左側牆位置（m）
		x0: 10,							// 初始位置（m）
		y0: 2,							// 初始位置（m）
		speed: 23,						// 初速（m/s）
		angleDeg: 10,					// 發球仰角（右→左）
		e: 0.55,						// 地面反彈係數（0~1）
		muK: 0.12,						// 著地瞬間的水平耗損比例
		muR: 0.04,						// 滾動阻力（無量綱）
		rollYThreshold: 0.5,			// 由彈跳轉「滾動」的垂直速度門檻（m/s）
		eWall: 0.5,					// 牆面反彈係數
		muRReturnMultiplier: 2.6,		// 回彈後的滾動阻力倍增
		simDT: 1 / 300,					// 物理時間步（秒）
		tmax: 20,						// 單次模擬最長時間（秒）

		// 播放
		autoplay: true,					// 載入後自動播放
		loop: true,						// 循環播放
		loopDelay: 0,					// 每輪結束後的停頓（毫秒）
		durationScale: 1,				// 整體播放時間縮放

		// 圖片
		ballImageSrc: '../../img/volleyballs-og/volleyball_1.webp',
		// ballImageSrc: '../../img/volleyballs/volleyball_1.webp',
		ballScale: 1.0,
		ballDiameterPx: null,           // 讓球跟著相機的「Y 尺度」自動等比，才能物理貼地

		// 壓縮
		compressKeyframes: true,
		keyframeMinDt: 1 / 30,
		keyframePxTol: 0.6,
		keyframeRotTolDeg: 8,
		keyframeMinDtRoll: 1 / 60,
		keyframePxTolRoll: 0.3,
		keyframeTailProtect: 1,

		// 旋轉
		spinRPS: 2.0,					// 初始自旋（每秒轉數）
		spinDir: 1,						// 旋轉方向（1 或 -1）
		spinAirDamping: 0.15,			// 空中自旋線性衰減係數（1/s）
		groundSpinBlend: 0.8,			// 每次接地時，朝「無滑動 ω = vx/r」的靠攏比例（0~1）
		wallSpinLoss: 0.8,				// 撞牆瞬間，旋轉能量的損失比例（0~1）
		spinVisualMultiplier: 1,		// 視覺自旋倍率

		// 相機裁切/縮放（不改 layout，用數學映射）
		cameraZoom: 2,                 // 放大 2 倍
		cameraAnchor: 'bl',            // bl=左下、br、tl、tr、center
		cameraOffset: { x: 0, y: 0 },  // 世界座標偏移
		cameraClamp: true,             // 超出世界邊界時夾回
		// groundPadPx: 12,               // 往上抬一點點，避免下緣被裁
		groundPadPx: 160,               // 往上抬一點點，避免下緣被裁
		aaSafetyPx: 1,                 // 抗鋸齒安全邊（像素）

		// 🔽 螢幕內邊距（像素）：避免球被視窗邊緣裁切
		// 預設 bottom='auto'：自動用旋轉最壞情況的最小安全值
		screenPadTopPx: 0,
		screenPadRightPx: 0,
		screenPadBottomPx: 'auto',
		screenPadLeftPx: 0,

		// 可視暫停
		observeVisibility: true,
		visibilityThreshold: 0.2
	};
	const opt = { ...defaults, ...userOptions };

	// 只移除我們自己的 svg
	container.querySelectorAll(':scope > svg.vb-svg').forEach(el => el.remove());

	const svgNS = 'http://www.w3.org/2000/svg';
	const svg = document.createElementNS(svgNS, 'svg');
	svg.classList.add('vb-svg');
	svg.setAttribute('width', '100%');
	svg.setAttribute('height', '100%');
	svg.style.display = 'block';
	container.appendChild(svg);

	const bbox = () => svg.getBoundingClientRect();
	let W = 1, H = 1;
	function resize() {
		const r = bbox();
		W = Math.max(1, r.width);
		H = Math.max(1, r.height || 280);
	}
	resize();
	window.addEventListener('resize', resize, { passive: true });

	// 世界座標
	// const world = { xMin: opt.wallX, xMax: opt.netX, yMin: -0.1, yMax: 3.8 };
	const world = { xMin: opt.wallX, xMax: opt.netX, yMin: 0, yMax: 3.8 };

	// 相機矩形（用來裁切/縮放顯示）
	const cam = { xMin: 0, xMax: 0, yMin: 0, yMax: 0 };
	function updateCamera() {
		const fullW = world.xMax - world.xMin;
		const fullH = world.yMax - world.yMin;
		const zoom  = Math.max(1, opt.cameraZoom || 1);
		const camW  = fullW / zoom;
		const camH  = fullH / zoom;

		let xMin, yMin;
		switch ((opt.cameraAnchor || 'center').toLowerCase()) {
			case 'bl': xMin = world.xMin;              yMin = world.yMin;              break;
			case 'br': xMin = world.xMax - camW;       yMin = world.yMin;              break;
			case 'tl': xMin = world.xMin;              yMin = world.yMax - camH;       break;
			case 'tr': xMin = world.xMax - camW;       yMin = world.yMax - camH;       break;
			default:   xMin = world.xMin + (fullW-camW)/2; yMin = world.yMin + (fullH-camH)/2;
		}

		// 偏移與夾限
		xMin += (opt.cameraOffset?.x || 0);
		yMin += (opt.cameraOffset?.y || 0);
		if (opt.cameraClamp !== false) {
			xMin = Math.max(world.xMin, Math.min(xMin, world.xMax - camW));
			yMin = Math.max(world.yMin, Math.min(yMin, world.yMax - camH));
		}

		cam.xMin = xMin;
		cam.yMin = yMin;
		cam.xMax = xMin + camW;
		cam.yMax = yMin + camH;
	}
	updateCamera();

	// 🔽 螢幕內邊距（像素）
	const PAD = { t: 0, r: 0, b: 0, l: 0 };

	// 以相機矩形換算畫面座標（加入螢幕 padding）
	const mx = (x) => {
		return PAD.l + ((x - cam.xMin) / (cam.xMax - cam.xMin)) * (W - PAD.l - PAD.r);
	};
	const my = (y) => {
		return (H - PAD.b) - ((y - cam.yMin) / (cam.yMax - cam.yMin)) * (H - PAD.t - PAD.b);
	};

	// 結構：<g class="vb-move"> 包 <image>
	const gMove = document.createElementNS(svgNS, 'g');
	const img = document.createElementNS(svgNS, 'image');
	img.setAttribute('href', opt.ballImageSrc);
	img.setAttributeNS('http://www.w3.org/1999/xlink', 'href', opt.ballImageSrc);
	img.setAttribute('preserveAspectRatio', 'xMidYMid meet');
	gMove.appendChild(img);
	svg.appendChild(gMove);

	let ballPx = 20;
	function sizeBall() {
		// 以相機高度換算像素比例，確保球的物理半徑 → 像素半徑對得上
		const camH = (cam.yMax - cam.yMin);
		const pxPerMeterY = H / camH;

		if (opt.ballDiameterPx && Number.isFinite(opt.ballDiameterPx)) {
			ballPx = opt.ballDiameterPx;
		} else {
			ballPx = Math.max(12, 2 * opt.r * pxPerMeterY) * (opt.ballScale || 1);
		}

		img.setAttribute('width',  ballPx);
		img.setAttribute('height', ballPx);
		img.setAttribute('x', -ballPx / 2);
		// groundPadPx：正值=往上抬，負值=往下壓
		img.setAttribute('y', -ballPx / 2 - (opt.groundPadPx || 0));
		gsap.set(img, { transformOrigin: '50% 50%' });

		// === 重新計算畫面 padding（特別是底部），避免旋轉時被裁邊 ===
		const rotateWorstExtra = Math.ceil(0.5 * ballPx * (Math.SQRT2 - 1)); // ≈ 0.2071 * ballPx
		const aaSafety = Math.max(0, Number(opt.aaSafetyPx || 1));           // 抗鋸齒安全邊
		const autoBottom = rotateWorstExtra + aaSafety;

		PAD.t = Number(opt.screenPadTopPx)    || 0;
		PAD.r = Number(opt.screenPadRightPx)  || 0;
		PAD.l = Number(opt.screenPadLeftPx)   || 0;

		// 'auto' 時用最小但足夠的值（不再用 ballPx/2 那麼大）
		PAD.b = (opt.screenPadBottomPx === 'auto' || opt.screenPadBottomPx == null)
			? autoBottom
			: Math.max(0, Number(opt.screenPadBottomPx) || 0);
	}
	sizeBall();

	let tl = null;

	function build() {
		const samples = simulateTrajectory(opt);

		// 轉為 keyframes（畫面座標 + 每段真實 duration + 旋轉角度 + phase）
		let kfs = [];
		for (let i = 0; i < samples.length; i++) {
			const s = samples[i];
			const dt = Math.max(0.0001, (s.dt || opt.simDT) * (opt.durationScale || 1));
			kfs.push({
				x: mx(s.x),
				y: my(s.y),
				rotation: (s.rot || 0) * 180 / Math.PI,
				duration: dt,
				phase: s.phase || 'flight'
			});
		}

		if (opt.compressKeyframes) {
			kfs = compressKeyframesSmart(kfs, {
				minDt: opt.keyframeMinDt,
				pxTol: opt.keyframePxTol,
				rotTolDeg: opt.keyframeRotTolDeg,
				minDtRoll: opt.keyframeMinDtRoll,
				pxTolRoll: opt.keyframePxTolRoll,
				tailProtect: opt.keyframeTailProtect
			});
			// console.log('[vb] kf before/after:', samples.length, kfs.length);
		}

		const kfPos = kfs.map(k => ({ x: k.x, y: k.y, duration: k.duration }));
		const kfRot = kfs.map(k => ({ rotation: k.rotation, duration: k.duration }));

		if (tl) tl.kill();
		tl = gsap.timeline({
			paused: true,
			repeat: opt.loop ? -1 : 0,
			repeatDelay: opt.loop ? opt.loopDelay / 1000 : 0,
			defaults: { ease: 'none' }
		});

		if (kfs.length) {
			gsap.set(gMove, { x: kfs[0].x, y: kfs[0].y });
			gsap.set(img,   { rotation: kfs[0].rotation, transformOrigin: '50% 50%' });
		}

		tl.to(gMove, { keyframes: kfPos, ease: 'none' }, 0);
		tl.to(img,   { keyframes: kfRot, ease: 'none' }, 0);
	}

	const imgEl = new Image();
	imgEl.onload = () => { sizeBall(); build(); if (opt.autoplay && tl) tl.play(); };
	imgEl.onerror = () => { build(); if (opt.autoplay && tl) tl.play(); };
	imgEl.src = opt.ballImageSrc;

	function rebuild() {
		resize();
		updateCamera();  // 先更新相機
		sizeBall();      // 依新尺寸重算 padding
		build();
	}

	let io = null; // IntersectionObserver 參考（銷毀用）

	const api = {
		play: () => tl && tl.play(),
		pause: () => tl && tl.pause(),
		resize: () => rebuild(),
		destroy: () => {
			if (tl) tl.kill();
			window.removeEventListener('resize', resize);
			if (io) { io.disconnect(); io = null; }
		}
	};

	// 可視暫停（避免背景耗電）
	if (opt.observeVisibility && 'IntersectionObserver' in window) {
		io = new IntersectionObserver((entries) => {
			entries.forEach(e => {
				if (!tl) return;
				if (e.isIntersecting && e.intersectionRatio >= (opt.visibilityThreshold || 0.2)) tl.play();
				else tl.pause();
			});
		}, { threshold: [0, opt.visibilityThreshold || 0.2, 1] });
		io.observe(container);
	}

	// 對外把控制器掛在 DOM 上，避免重複初始化
	container.__vbCtrl = api;
	return api;
}

/* -------------------------------------------------
4) 自動初始化（副作用匯入即可）
- 預設找 #vbScene
- 也讀 #vbScene 的 data-* 屬性覆蓋參數
可用 data-* 範例：
	data-ball-src="/assets/volleyball.webp"
	data-ball-scale="1.2"
	data-ball-px="64"
	data-autoplay="true"
	data-loop="true"
	data-loop-delay="1200"
	data-speed="14"
	data-angle="20"
	data-wall-x="-10"
	data-net-x="3.8"
	data-observe-visibility="true"
	data-camera-zoom="2"
	data-camera-anchor="bl"
	data-camera-offset-x="0"
	data-camera-offset-y="0"
	data-camera-clamp="true"
	data-screen-pad-bottom-px="auto"
	data-screen-pad-top-px="0"
	data-screen-pad-left-px="0"
	data-screen-pad-right-px="0"
------------------------------------------------- */
function parseBool(v) {
	if (typeof v === 'boolean') return v;
	if (typeof v !== 'string') return undefined;
	return /^(1|true|yes|on)$/i.test(v) ? true : /^(0|false|no|off)$/i.test(v) ? false : undefined;
}
function parseNum(v) {
	const n = Number(v);
	return Number.isFinite(n) ? n : undefined;
}
function readOptionsFromDataset(el) {
	const d = el.dataset || {};
	const map = {
		ballSrc: 'ballImageSrc',
		ballScale: 'ballScale',
		ballPx: 'ballDiameterPx',
		autoplay: 'autoplay',
		loop: 'loop',
		loopDelay: 'loopDelay',
		speed: 'speed',
		angle: 'angleDeg',
		wallX: 'wallX',
		netX: 'netX',
		observeVisibility: 'observeVisibility',
		// 相機
		cameraZoom: 'cameraZoom',
		cameraAnchor: 'cameraAnchor',
		cameraClamp: 'cameraClamp',
		cameraOffsetX: 'cameraOffsetX',
		cameraOffsetY: 'cameraOffsetY',
		// 螢幕 padding
		screenPadTopPx: 'screenPadTopPx',
		screenPadRightPx: 'screenPadRightPx',
		screenPadBottomPx: 'screenPadBottomPx',
		screenPadLeftPx: 'screenPadLeftPx'
	};
	const out = {};
	Object.keys(map).forEach(k => {
		const v = d[k];
		if (v == null) return;
		const key = map[k];
		if (key === 'autoplay' || key === 'loop' || key === 'observeVisibility' || key === 'cameraClamp') {
			const b = parseBool(v);
			if (b !== undefined) out[key] = b;
		} else if (key === 'cameraAnchor') {
			out[key] = v;
		} else if (key === 'screenPadBottomPx' && (v === 'auto' || v === 'AUTO')) {
			out[key] = 'auto';
		} else {
			const n = parseNum(v);
			out[key] = (n !== undefined) ? n : v;
		}
	});
	// 組 offset
	const ox = parseNum(d.cameraOffsetX);
  	const oy = parseNum(d.cameraOffsetY);
	if (ox !== undefined || oy !== undefined) {
		out.cameraOffset = { x: ox || 0, y: oy || 0 };
	}
	return out;
}

(function autoInit() {
	const run = () => {
		const el = document.querySelector('#vbScene');
		if (!el || el.__vbCtrl) return;
		const dsOpt = readOptionsFromDataset(el);
		const ctrl = initVolleyball(el, dsOpt);
		// 偶爾需要手動控制可在 console 取用
		window.vbCtrl = ctrl;
	};
	if (document.readyState !== 'loading') run();
	else document.addEventListener('DOMContentLoaded', run, { once: true });
})();